document.addEventListener("DOMContentLoaded",function(){const t=document.getElementById("register-form");t&&t.addEventListener("submit",function(e){e.preventDefault(),(e=new FormData(this)).append("action","register"),fetch("../controllers/AuthController.php",{method:"POST",body:e}).then(e=>e.json()).then(e=>{if(e.success)Toastify({text:e.message,duration:3e3,className:"info",style:{background:"linear-gradient(to right, #00b09b, #96c93d)"}}).showToast(),t.reset();else{let s=e.message||"";if(e.errors)for(const o in e.errors)e.errors[o]&&(s+=e.errors[o]+"\n");Toastify({text:s,duration:3e3,className:"error",style:{background:"linear-gradient(to right, #ff5f6d, #ffc371)"}}).showToast()}}).catch(e=>{console.error("Error:",e),Toastify({text:"A network error occurred.",duration:3e3,className:"error",style:{background:"linear-gradient(to right, #ff5f6d, #ffc371)"}}).showToast()})});const s=document.getElementById("login-form");s&&s.addEventListener("submit",function(e){e.preventDefault(),(e=new FormData(this)).append("action","login"),fetch("../controllers/AuthController.php",{method:"POST",body:e}).then(e=>e.json()).then(e=>{if(e.success)window.location.href="../php/dashboard.php";else{let t=e.message||"";if(e.errors)for(const o in e.errors)e.errors[o]&&(t+=e.errors[o]+"\n");Toastify({text:t,duration:3e3,className:"error",style:{background:"linear-gradient(to right, #ff5f6d, #ffc371)"}}).showToast()}}).catch(e=>{console.error("Error:",e),Toastify({text:"A network error occurred.",duration:3e3,className:"error",style:{background:"linear-gradient(to right, #ff5f6d, #ffc371)"}}).showToast()})})});
